import{_ as n,c as a,o as s,ag as t}from"./chunks/framework.CQuhCYrb.js";const h=JSON.parse('{"title":"Evaluation AI Prompt","description":"","frontmatter":{"title":"Evaluation AI Prompt"},"headers":[],"relativePath":"ai-ml/evaluation-ai-prompt.md","filePath":"ai-ml/evaluation-ai-prompt.md","lastUpdated":null}'),r={name:"ai-ml/evaluation-ai-prompt.md"};function i(o,e,l,p,c,m){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="evaluation-ai-prompt" tabindex="-1">Evaluation AI Prompt <a class="header-anchor" href="#evaluation-ai-prompt" aria-label="Permalink to &quot;Evaluation AI Prompt&quot;">​</a></h1><h2 id="senior-rating" tabindex="-1">Senior Rating <a class="header-anchor" href="#senior-rating" aria-label="Permalink to &quot;Senior Rating&quot;">​</a></h2><p>The Noncommissioned Officer Evaluation Reporting System (NCOER) is governed by Army Regulation (AR) 623-3 and <a href="http://thenewoer.com/presentation_content/external_files/DA%20Pam%20623-3%20Dated%2031%20March%202014.pdf" target="_blank" rel="noreferrer">DA PAM 623-3</a>, which establish the policies, responsibilities, and procedures for evaluating NCOs. The system is designed to assess an NCO’s performance and potential, with a focus on leadership, technical skills, and overall mission contribution.</p><p>According to AR 623-3, Senior Raters play a critical role in documenting an NCO’s future potential. They provide an objective and fair assessment that focuses on the NCO’s readiness for increased responsibility, promotion, and future leadership roles. Senior Rater comments should be concise and include peer comparisons, enumeration, and recommendations for career development, such as promotion or advanced schooling.</p><p>DA PAM 623-3 provides detailed instructions on how to write effective Senior Rater comments, emphasizing the importance of focusing on potential rather than past performance. Senior Raters are required to base their evaluations on the NCO’s contributions during the rating period and forecast their ability to excel in future assignments.</p><h3 id="guidance-for-senior-rating" tabindex="-1">Guidance for Senior Rating <a class="header-anchor" href="#guidance-for-senior-rating" aria-label="Permalink to &quot;Guidance for Senior Rating&quot;">​</a></h3><p>The following rules apply:</p><p><em>a.</em> The senior rater’s signature and date cannot be before the rater’s or intermediate rater’s signatures.</p><p><em>b.</em> The rated officer’s signature and date cannot be before the rater’s, the intermediate rater’s, or the senior rater’s</p><p>signatures.</p><p><strong>NCOER part V:</strong> block c-Senior Rater-Overall performance</p><p><strong>Action required:</strong> Senior rater evaluates overall performance by placing an “X” in the appropriate box. The senior rater’s box marks are independent of the rater’s. There is no specific box mark ratings required of the senior rater based on box marks made by the rater. The following definitions will be used when completing block c:</p><p><strong>Table 3–5</strong></p><ul><li><p><strong>NCOER part V:</strong> block d-Senior Rater-Overall potential for promotion and/or service in positions of greater responsibility <strong>Action required:</strong> Senior rater evaluates overall potential by placing an “X” in the appropriate box. The senior rater’s box marks are independent of the rater’s. There is no specific box mark ratings required of the senior rater based on box marks made by the rater. The following definitions will be used when completing block d:</p></li><li><p>Successful/Superior. A “1” rating represents the cream of the crop and is a recommendation for immediate promotion.</p></li><li><p>A “2” rating represents a very good, strong recommendation for promotion.</p></li><li><p>A “3” rating also represents a recommendation for promotion should sufficient allocations be available.</p></li><li><p>Fair. A “4” rating represents NCOs who may require additional training and/or observation and should not be promoted at this time.</p></li><li><p>Poor. A “5” rating represents NCOs who are weak or deficient and, in the opinion of the senior rater, need significant improvement or training in one or more areas. Do not promote and consider for DA imposed bar to reenlistment under the Qualitative Management Program.</p></li><li><p><strong>Reference:</strong> None <strong>NCOER part V:</strong> block e-Senior Rater Bullet Comments <strong>Action required:</strong> When the senior rater does not meet minimum time requirements for evaluation of the rated NCO, he or she will enter the following statement: “Senior rater does not meet minimum qualifications.” Part V, blocks c and d will not be completed, but the senior rater will sign the NCOER. Otherwise, bullet comments are mandatory. The senior rater must address any “Fair” or “Poor” ratings. If the senior rater meets the minimum time qualifications for evaluation, he or she must make bullet comments on potential and performance. The senior rater must address the lack of a rated NCO’s signature on the NCOER. Note. If the rated NCO is physically unavailable to sign (and cannot have it forwarded to him or her to sign), unable to sign, or refuses to sign the NCOER, for any reason, the senior rater will either resolve the problem or use the Wizard application associated with the electronic form within the Evaluation Entry System portal to automatically enter the appropriate statement explaining why the rated NCO’s signature is left blank in part II, block e. Otherwise, the electronic form within the Evaluation Entry System portal may not allow the NCOER to be submitted. NCOERs stating that the NCO cannot sign due to CAC issues will not be processed. The NCOER will not be delayed because it lacks the rated NCO’s signature. In those cases when the senior rater is serving as both rater and senior rater, enter a bullet comment to explain why, such as “Rater relieved” or “Serving as rater and senior rater in accordance with AR 623–3, paragraph 2–19” (or para 2–20) as appropriate. There is no requirement for the entry of this statement for GO and SES members serving in accordance with AR 623–3. Senior raters will comment on any substantiated finding, in an Army or DOD investigation or inquiry, that a rated NCO— —Committed an act of sexual harassment or sexual assault. —Failed to report a sexual harassment or assault. —Failed to respond to a complaint or report of sexual harassment or sexual assault. —Retaliated against a person making a complaint or report of sexual harassment or sexual assault. NCOs who are found with substantiated SHARP, EO, and/or EEO complaints resulting from an AR 15–6 investigation or other official investigation by military or civil authorities, the senior rater will annotate a bullet comment “does not support SHARP, EO, and EEO.”</p></li></ul><h3 id="how-to-use-template" tabindex="-1">How To Use Template <a class="header-anchor" href="#how-to-use-template" aria-label="Permalink to &quot;How To Use Template&quot;">​</a></h3><ol><li>Find a LLM to use on commercial or government networks <a href="/ai-ml/ai-resources.html">Resources</a></li><li>Talk with Soldier and Rater etc</li><li>Copy the template below directly into a chatbot</li><li>Fill in the Variables and the NCOER content at the bottom of the template</li><li>Generate.</li><li>Review and Improve.</li><li>Generate.</li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>Start of Variables:</span></span>
<span class="line"><span>MOS: MOS_HERE</span></span>
<span class="line"><span>RANK= RANK_HERE</span></span>
<span class="line"><span>Last Name = LAST_HERE</span></span>
<span class="line"><span>Position = POSITION_HERE\u2028</span></span>
<span class="line"><span>Rating: 1(bad) - 5(outstanding):</span></span>
<span class="line"><span>Enumeration = X of X_TOTAL</span></span>
<span class="line"><span>Recommended Future Positions:</span></span>
<span class="line"><span>End of Variables:</span></span>
<span class="line"><span>Prompt:</span></span>
<span class="line"><span>\u2028\u2028Write Senior Rater comments for [[Last Name](Rank]), who serves as a [based on [Rating](Position]) . Highlight their key achievements and unique skills. Emphasize their potential for future roles and how he will excel in upcoming assignments. Mention that he is among the top [of NCOs I have rated if their performance is outstanding. Include specific recommendations for promotion, education, and future assignments, such as ‘must select for [next NCOES](RATING%]),’ ‘promote ahead of peers,’ or ‘assign to leadership roles at the brigade level.’</span></span>
<span class="line"><span></span></span>
<span class="line"><span>If their performance is not as exceptional, provide a balanced view that acknowledges their strengths while suggesting areas for improvement or growth. Ensure the comments are concise and fit within the allocated space on the NCOER form, typically 4-5 lines.</span></span>
<span class="line"><span>End of Prompt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Start of Rules</span></span>
<span class="line"><span>1. Provide Basic Information</span></span>
<span class="line"><span>• Include the NCO’s name, rank, and position.</span></span>
<span class="line"><span>• Specify any key achievements, unique skills, or characteristics that should be emphasized.</span></span>
<span class="line"><span>2. Focus on Potential</span></span>
<span class="line"><span>• Senior Rater comments should focus on potential rather than past performance. Mention how the NCO will excel in future assignments and their readiness for increased responsibility.</span></span>
<span class="line"><span>3. Enumerate</span></span>
<span class="line"><span>• Include a peer comparison, such as “top 5% of NCOs I have senior rated” or “#1 of 10 SGTs in the unit.” Ttheir helps quantify their ranking and potential.</span></span>
<span class="line"><span>4. Use Specific Recommendations</span></span>
<span class="line"><span>• Recommend education, promotion, and future assignments. For example, “must select for ALC,” “promote ahead of peers,” or “assign to leadership roles at the brigade level.”</span></span>
<span class="line"><span>5. Stay within the Character Limit</span></span>
<span class="line"><span>• Ensure the comments fit within the space allocated on the NCOER form (usually 4-5 lines).</span></span>
<span class="line"><span>6. Avoid Overemphasis on specific Performance</span></span>
<span class="line"><span>• While performance can be acknowledged briefly, the emphasis should be on overall and future success and how the NCO’s potential sets them apart compared to their peers.</span></span>
<span class="line"><span>End of Rules</span></span>
<span class="line"><span></span></span>
<span class="line"><span>NCOER Bullets for context:</span></span>
<span class="line"><span>CONTENTGOESHERE</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\u2028Example Senior rater comments: notice the word count, order and tone.\u2028\u2028SENIOR RATER COMMENTS</span></span>
<span class="line"><span>SGT D&#39;s potential as an NCO and a Squad Leader is unmeasurable. He is, by far, the #1 of 3 squad leaders that I senior rate. SGT D has the knowledge and work ethic to be an outstanding Squad Leader or Section Sergeant. SGT D has the tools to serve in any position that the Army has to offer and succeed. Continue to challenge this NCO with greater responsibilities. Send to ALC immediately and promote ahead of peers.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SFC Doe is one of the absolute best SFC on Fort Xxxx and easily in the top 10% of NCOs I have worked with in 31 years. Her professional acumen, command presence, and leadership made an immeasurable impact to the success of the Command Group and Fort Xxxx. Select for Master Sergeant now and send to MLC, Soldiers need her Leadership!</span></span>
<span class="line"><span>\u2028SSG Elizondo ranks 1 of 4 Staff Sergeants I currently senior rate. He is a top notch NCO who expects and enjoys a challenge. SSG Elizondo instilled confidence within subordinates and set an example for all to emulate. SSG Elizondo is a self-starter; he identifies problems early and develops strategies to address them. New soldiers and officers look to him for guidance. Promote now to Sergeant First Class.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SSG Brooks is 1 of 3 Staff Sergeant&#39;s I currently senior rate. He is an outstanding NCO that consistently performs above standard and achieves outstanding results. Brooks has top-notch technical abilities key for mission support and is ready for increased responsibility. Continue to place in tough, demanding leadership jobs. SSG Brooks is a must select for promotion.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>An exceptional NCO and easily in the top 10% of all NCOs I rate. He is ready to assume greater responsibilities. He is capable of overseeing major construction operations while coordinating other mission critical tasks. He can communicate a clear vision to subordinates and peers and fosters a command team spirit within the company. Promote to Sergeant First Class now.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SSG Garcia is an organized and disciplined leader, addressing situations with tenacity and zeal. His commitment to the organization is what others should emulate. Challenge with greater responsibilities and promote to Sergeant First Class now.</span></span>
<span class="line"><span>End of NCOER Bullets</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br></div></div><p>[Template] [Template]</p>`,18)])])}const u=n(r,[["render",i]]);export{h as __pageData,u as default};
